import{_ as n,o as t,c as s,ag as r}from"./chunks/framework.C15dTZqp.js";const m=JSON.parse(`{"title":"Bien demander","description":"","frontmatter":{},"headers":[],"relativePath":"handout-02-bien-demander.md","filePath":"handout-02-bien-demander.md","handout":{"fichier":"handout-02-bien-demander.md","markdown":"# Handout — Bien demander\\n\\n**Speed training IA · Zenika · fiche module 2**\\n\\nD'une demande floue à une sortie exploitable : quoi donner à l'IA, dans quel ordre, et comment réutiliser ce qui marche.\\n\\n## Les 4 ingrédients d'une bonne demande\\n\\n| Ingrédient          | La question                                               | Exemple                                          |\\n| ------------------- | --------------------------------------------------------- | ------------------------------------------------ |\\n| **Rôle / contexte** | Quel rôle l'IA doit jouer, sur quel sujet se concentrer ? | « Tu es PO d'un site de réservation hôtelière. » |\\n| **Sortie attendue** | Quel format, quelle structure, quelle longueur ?          | « Une user story + 3 critères d'acceptation. »   |\\n| **Règles**          | Qu'est-ce qui est précis, mesurable, non négociable ?     | « Cible : clients sur mobile. »                  |\\n| **À éviter**        | Qu'est-ce qu'elle ne doit pas faire ou inclure ?          | « N'invente pas de chiffres. »                   |\\n\\n**Montrer un exemple** du format attendu vaut mieux qu'une longue description : c'est le **few-shot**.\\n\\nModèle à copier :\\n\\n\`\`\`text\\nTu es [rôle], tu travailles sur [sujet].\\nProduis [livrable], au format [structure, longueur].\\nRègles : [cible, contraintes, éléments obligatoires].\\nÀ éviter : [ce qu'il ne faut pas inventer ou inclure].\\nExemple du format attendu : [un exemple court].\\n\`\`\`\\n\\n## Clarifier avant de produire\\n\\n1. **Besoin flou** : le besoin tel qu'on l'exprime à l'oral (« améliorer la réservation »).\\n2. **Brief structuré** : l'IA propose une structure (objectif, cible, contraintes, format), **vous la corrigez et la validez**.\\n3. **Livrable** : produit à partir du brief validé, pas du besoin flou.\\n\\nLa sortie d'une étape devient le **contexte** de la suivante. On ne demande pas tout d'un coup : on demande d'abord une structure vérifiable.\\n\\n\`\`\`text\\nOn veut réduire les abandons de réservation sur mobile.\\nPropose-moi d'abord un brief : objectif, cible, contraintes,\\nformat attendu. Ne rédige pas encore la user story.\\n\`\`\`\\n\\n## Rewind plutôt qu'empiler\\n\\nQuand une réponse part mal, la tentation est d'enchaîner les corrections (« non, pas comme ça… »). Chaque correction reste dans la conversation et le contexte devient de plus en plus confus.\\n\\nLe bon réflexe : **revenir à la demande de départ** (bouton « Modifier » de votre message), la corriger, et relancer. Une mauvaise sortie est une **information sur l'entrée**, pas un texte à corriger.\\n\\n## Un bon brief devient un actif\\n\\nUn brief qui marche sur **deux sujets différents** est réutilisable. Trois façons de le capitaliser :\\n\\n1. **Instructions personnalisées** : toujours chargées (ton, langue, profil).\\n2. **Assistant personnalisé** : un espace dédié (GPT, Projet Claude, agent Copilot).\\n3. **Skill** : chargé **à la demande**, quand la tâche correspond (consignes, modèles, exemples).\\n\\nExemple d'assistant « User stories » :\\n\\n\`\`\`text\\nTu es PO de l'équipe Réservation.\\nPour chaque besoin que je te donne :\\n1. Propose d'abord un brief : objectif, cible, contraintes, format.\\n2. Attends ma validation.\\n3. Rédige la user story + 3 critères d'acceptation.\\nTon clair, sans jargon. N'invente ni chiffres ni dépendances.\\n\`\`\`\\n\\nAttention au vocabulaire : les éditeurs appellent souvent ces assistants personnalisés des « agents ». Au sens strict, un agent est un modèle qui enchaîne lui-même des tools en boucle (voir la fiche 1).\\n\\n## À retenir\\n\\n1. Écrivez votre demande avec les **4 ingrédients**, et montrez un exemple.\\n2. Demandez une **structure**, validez-la, puis demandez le livrable.\\n3. Une réponse ratée : **rewind**, pas une correction de plus.\\n4. Ce qui marche deux fois devient un **assistant** ou un **skill** d'équipe.\\n\\n**Mots-clés** : prompt, brief structuré, few-shot, rewind, instructions personnalisées, assistant personnalisé, skill — voir le glossaire.\\n"}}`),a={name:"handout-02-bien-demander.md"};function i(o,e,l,u,d,p){return t(),s("div",null,[...e[0]||(e[0]=[r(`<p class="zh-type">fiche module 2</p><h1 id="handout-bien-demander" tabindex="-1">Bien demander <a class="header-anchor" href="#handout-bien-demander" aria-label="Permalink to &quot;Handout — Bien demander&quot;">​</a></h1><p>D’une demande floue à une sortie exploitable : quoi donner à l’IA, dans quel ordre, et comment réutiliser ce qui marche.</p><h2 id="les-4-ingredients-d-une-bonne-demande" tabindex="-1">Les 4 ingrédients d’une bonne demande <a class="header-anchor" href="#les-4-ingredients-d-une-bonne-demande" aria-label="Permalink to &quot;Les 4 ingrédients d&#39;une bonne demande&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ingrédient</th><th>La question</th><th>Exemple</th></tr></thead><tbody><tr><td><strong>Rôle / contexte</strong></td><td>Quel rôle l’IA doit jouer, sur quel sujet se concentrer ?</td><td>« Tu es PO d’un site de réservation hôtelière. »</td></tr><tr><td><strong>Sortie attendue</strong></td><td>Quel format, quelle structure, quelle longueur ?</td><td>« Une user story + 3 critères d’acceptation. »</td></tr><tr><td><strong>Règles</strong></td><td>Qu’est-ce qui est précis, mesurable, non négociable ?</td><td>« Cible : clients sur mobile. »</td></tr><tr><td><strong>À éviter</strong></td><td>Qu’est-ce qu’elle ne doit pas faire ou inclure ?</td><td>« N’invente pas de chiffres. »</td></tr></tbody></table><p><strong>Montrer un exemple</strong> du format attendu vaut mieux qu’une longue description : c’est le <strong>few-shot</strong>.</p><p>Modèle à copier :</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tu es [rôle], tu travailles sur [sujet].</span></span>
<span class="line"><span>Produis [livrable], au format [structure, longueur].</span></span>
<span class="line"><span>Règles : [cible, contraintes, éléments obligatoires].</span></span>
<span class="line"><span>À éviter : [ce qu&#39;il ne faut pas inventer ou inclure].</span></span>
<span class="line"><span>Exemple du format attendu : [un exemple court].</span></span></code></pre></div><h2 id="clarifier-avant-de-produire" tabindex="-1">Clarifier avant de produire <a class="header-anchor" href="#clarifier-avant-de-produire" aria-label="Permalink to &quot;Clarifier avant de produire&quot;">​</a></h2><ol><li><strong>Besoin flou</strong> : le besoin tel qu’on l’exprime à l’oral (« améliorer la réservation »).</li><li><strong>Brief structuré</strong> : l’IA propose une structure (objectif, cible, contraintes, format), <strong>vous la corrigez et la validez</strong>.</li><li><strong>Livrable</strong> : produit à partir du brief validé, pas du besoin flou.</li></ol><p>La sortie d’une étape devient le <strong>contexte</strong> de la suivante. On ne demande pas tout d’un coup : on demande d’abord une structure vérifiable.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>On veut réduire les abandons de réservation sur mobile.</span></span>
<span class="line"><span>Propose-moi d&#39;abord un brief : objectif, cible, contraintes,</span></span>
<span class="line"><span>format attendu. Ne rédige pas encore la user story.</span></span></code></pre></div><h2 id="rewind-plutot-qu-empiler" tabindex="-1">Rewind plutôt qu’empiler <a class="header-anchor" href="#rewind-plutot-qu-empiler" aria-label="Permalink to &quot;Rewind plutôt qu&#39;empiler&quot;">​</a></h2><p>Quand une réponse part mal, la tentation est d’enchaîner les corrections (« non, pas comme ça… »). Chaque correction reste dans la conversation et le contexte devient de plus en plus confus.</p><p>Le bon réflexe : <strong>revenir à la demande de départ</strong> (bouton « Modifier » de votre message), la corriger, et relancer. Une mauvaise sortie est une <strong>information sur l’entrée</strong>, pas un texte à corriger.</p><h2 id="un-bon-brief-devient-un-actif" tabindex="-1">Un bon brief devient un actif <a class="header-anchor" href="#un-bon-brief-devient-un-actif" aria-label="Permalink to &quot;Un bon brief devient un actif&quot;">​</a></h2><p>Un brief qui marche sur <strong>deux sujets différents</strong> est réutilisable. Trois façons de le capitaliser :</p><ol><li><strong>Instructions personnalisées</strong> : toujours chargées (ton, langue, profil).</li><li><strong>Assistant personnalisé</strong> : un espace dédié (GPT, Projet Claude, agent Copilot).</li><li><strong>Skill</strong> : chargé <strong>à la demande</strong>, quand la tâche correspond (consignes, modèles, exemples).</li></ol><p>Exemple d’assistant « User stories » :</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tu es PO de l&#39;équipe Réservation.</span></span>
<span class="line"><span>Pour chaque besoin que je te donne :</span></span>
<span class="line"><span>1. Propose d&#39;abord un brief : objectif, cible, contraintes, format.</span></span>
<span class="line"><span>2. Attends ma validation.</span></span>
<span class="line"><span>3. Rédige la user story + 3 critères d&#39;acceptation.</span></span>
<span class="line"><span>Ton clair, sans jargon. N&#39;invente ni chiffres ni dépendances.</span></span></code></pre></div><p>Attention au vocabulaire : les éditeurs appellent souvent ces assistants personnalisés des « agents ». Au sens strict, un agent est un modèle qui enchaîne lui-même des tools en boucle (voir la fiche 1).</p><h2 id="a-retenir" tabindex="-1">À retenir <a class="header-anchor" href="#a-retenir" aria-label="Permalink to &quot;À retenir&quot;">​</a></h2><ol><li>Écrivez votre demande avec les <strong>4 ingrédients</strong>, et montrez un exemple.</li><li>Demandez une <strong>structure</strong>, validez-la, puis demandez le livrable.</li><li>Une réponse ratée : <strong>rewind</strong>, pas une correction de plus.</li><li>Ce qui marche deux fois devient un <strong>assistant</strong> ou un <strong>skill</strong> d’équipe.</li></ol><p><strong>Mots-clés</strong> : prompt, brief structuré, few-shot, rewind, instructions personnalisées, assistant personnalisé, skill — voir le glossaire.</p>`,24)])])}const b=n(a,[["render",i]]);export{m as __pageData,b as default};
